using System;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;
namespace DoomSNESed {
    public sealed partial class ConverterForm {
        void AddCopyrightTab(){var tab=new TabPage("Copyright"){BackColor=Theme.Panel};tabs.TabPages.Add(tab);var split=new SplitContainer{Dock=DockStyle.Fill,Width=1160,SplitterDistance=590};tab.Controls.Add(split);
            var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55,Padding=new Padding(8)};var load=Theme.Button("Load from base ROM");var reset=Theme.Button("Restore original");tools.Controls.Add(load);tools.Controls.Add(reset);var status=new Label{Dock=DockStyle.Bottom,Height=78,Padding=new Padding(8),ForeColor=Theme.Mint};
            var rows=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Theme.Background,ForeColor=Color.Black};rows.Columns.Add(new DataGridViewTextBoxColumn{Name="Row (0..27)",FillWeight=50});rows.Columns.Add(new DataGridViewTextBoxColumn{Name="Column",FillWeight=45});rows.Columns.Add(new DataGridViewTextBoxColumn{Name="Text",FillWeight=220});split.Panel1.Controls.Add(rows);split.Panel1.Controls.Add(status);split.Panel1.Controls.Add(tools);
            var preview=new NativeTextPreview{Dock=DockStyle.Fill,BackColor=Color.Black};split.Panel2.Controls.Add(preview);split.Panel2.Controls.Add(new Label{Dock=DockStyle.Top,Height=62,Padding=new Padding(8),ForeColor=Theme.Mint,Text="Opening copyright screen — native font, red on black\nLive preview. Supports ©, ® and ™. Empty text hides an entry."});
            Rom rom=null;bool loading=false;var timer=new Timer{Interval=120};Action redraw=delegate{if(rom==null)return;var old=preview.Image;preview.Image=CopyrightAssets.Preview(rom,textChanges.FirstOrDefault(t=>t.Id==CopyrightAssets.Id),graphicChanges);if(old!=null)old.Dispose();};
            Action stage=delegate{if(loading||rom==null)return;try{var replacement=new TextReplacement{Id=CopyrightAssets.Id,Lines=new System.Collections.Generic.List<CreditLine>()};foreach(DataGridViewRow row in rows.Rows){int y=0,x=0;Bin.Require(int.TryParse(Convert.ToString(row.Cells[0].Value),out y)&&int.TryParse(Convert.ToString(row.Cells[1].Value),out x),"Row and column must be whole numbers.");var line=new CreditLine{Record=(int)row.Tag,Row=y,Column=x,Text=Convert.ToString(row.Cells[2].Value)??""};CopyrightAssets.Validate(line);replacement.Lines.Add(line);}textChanges.RemoveAll(t=>t.Id==CopyrightAssets.Id);textChanges.Add(replacement);textErrors.Remove(CopyrightAssets.Id);status.ForeColor=Theme.Mint;status.Text="Staged. Rows 0–27, columns 0–31; each line must fit the screen. Build ROM to apply these edits.";AssetsChanged();redraw();}catch(Exception ex){textErrors[CopyrightAssets.Id]=ex.Message;status.ForeColor=Color.Salmon;status.Text="Not staged: "+ex.Message;}};
            Action populate=delegate{if(rom==null)return;loading=true;try{rows.Rows.Clear();var change=textChanges.FirstOrDefault(t=>t.Id==CopyrightAssets.Id);foreach(var line in change==null?CopyrightAssets.Read(rom.Bytes):change.Lines){int index=rows.Rows.Add(line.Row,line.Column,line.Text);rows.Rows[index].Tag=line.Record;}status.Text="Edits stage automatically. The preview uses this ROM's native text font.";status.ForeColor=Theme.Mint;redraw();}finally{loading=false;}};
            Action loadRom=delegate{try{rom=new Rom(romPath.Text,resources);populate();}catch(Exception ex){rom=null;status.Text=ex.Message;status.ForeColor=Color.Salmon;}};timer.Tick+=delegate{timer.Stop();stage();};rows.CellValueChanged+=delegate{if(!loading){timer.Stop();timer.Start();}};rows.CurrentCellDirtyStateChanged+=delegate{if(rows.IsCurrentCellDirty)rows.CommitEdit(DataGridViewDataErrorContexts.Commit);};textFlushers.Add(delegate{rows.EndEdit();if(timer.Enabled){timer.Stop();stage();}});load.Click+=delegate{loadRom();};reset.Click+=delegate{if(rom==null)return;timer.Stop();textChanges.RemoveAll(t=>t.Id==CopyrightAssets.Id);textErrors.Remove(CopyrightAssets.Id);AssetsChanged();populate();};tab.Leave+=delegate{rows.EndEdit();if(timer.Enabled){timer.Stop();stage();}};tabs.SelectedIndexChanged+=delegate{if(tabs.SelectedTab==tab){if(rom==null&&File.Exists(romPath.Text))loadRom();else populate();}};romPath.TextChanged+=delegate{timer.Stop();rom=null;rows.Rows.Clear();var old=preview.Image;preview.Image=null;if(old!=null)old.Dispose();if(tabs.SelectedTab==tab&&File.Exists(romPath.Text))loadRom();};FormClosed+=delegate{timer.Dispose();if(preview.Image!=null)preview.Image.Dispose();};
        }
    }
}

